    statement = statement.lower()
    positive_keywords = {'good', 'progress', 'success', 'benefit', 'improve'}
    negative_keywords = {'bad', 'failure', 'corruption', 'harm', 'decline'}

    for word in positive_keywords:
        if word in statement:
            return 'Positive'

    for word in negative_keywords:
        if word in statement:
            return 'Negative'

    return 'Neutral'",
